# Pricing helpers for the shop.

BULK_THRESHOLD = 10


def line_total(unit_price, qty):
    return round(unit_price * qty, 2)


def bulk_total(unit_price, qty):
    if qty < 0:
        raise ValueError('qty must not be negative')
    total = line_total(unit_price, qty)
    if qty > BULK_THRESHOLD:
        return round(total * 0.9, 2)
    return total


def average_price(prices):
    if not prices:
        return 0.0
    return round(sum(prices) / len(prices), 2)

